#include <algorithm>
#include <chrono>
#include <cmath>
#include <stdexcept>
#include <string>
#include <vector>

template <class F>
double bestOfMs(F work, int runs)
{
    if (runs < 1) throw std::invalid_argument("runs must be at least 1");
    double best = 1e300;
    for (int i = 0; i < runs; ++i)
    {
        auto start = std::chrono::steady_clock::now();
        work();
        auto stop = std::chrono::steady_clock::now();
        best = std::min(best, std::chrono::duration<double, std::milli>(stop - start).count());
    }
    return best;
}

double median(std::vector<double> samples)
{
    if (samples.empty()) throw std::invalid_argument("no samples");
    std::sort(samples.begin(), samples.end());
    std::size_t mid = samples.size() / 2;
    return samples.size() % 2 == 1 ? samples[mid] : (samples[mid - 1] + samples[mid]) / 2.0;
}

double growthExponent(const std::vector<double>& times)
{
    if (times.size() < 2) throw std::invalid_argument("need at least two times");
    for (double t : times)
        if (!(t > 0)) throw std::invalid_argument("times must be positive");
    double perDoubling = std::pow(times.back() / times.front(), 1.0 / static_cast<double>(times.size() - 1));
    return std::log2(perDoubling);
}

std::string bigO(double exponent)
{
    long k = std::lround(exponent);
    if (k <= 0) return "O(1)";
    if (k == 1) return "O(n)";
    if (k == 2) return "O(n^2)";
    if (k == 3) return "O(n^3)";
    return "worse than O(n^3)";
}

unitTests:
TEST("best of several runs") {
    int calls = 0;
    double ms = bestOfMs([&] { ++calls; }, 5);
    CHECK_EQ(calls, 5);
    CHECK(ms >= 0.0);
    CHECK(ms < 50.0);
    CHECK_THROWS(bestOfMs([] {}, 0));
}
TEST("a slow function takes measurable time") {
    volatile long long sink = 0;
    double ms = bestOfMs([&] { for (int i = 0; i < 3000000; ++i) sink = sink + i; }, 2);
    CHECK(ms > 0.0);
}
TEST("median") {
    CHECK_NEAR(median({ 5.0, 1.0, 3.0 }), 3.0, 1e-12);
    CHECK_NEAR(median({ 4.0, 1.0, 3.0, 2.0 }), 2.5, 1e-12);
    CHECK_NEAR(median({ 7.5 }), 7.5, 1e-12);
    CHECK_THROWS(median({}));
}
TEST("growth exponents") {
    CHECK_NEAR(growthExponent({ 10, 20, 40, 80 }), 1.0, 1e-9);
    CHECK_NEAR(growthExponent({ 1, 4, 16 }), 2.0, 1e-9);
    CHECK_NEAR(growthExponent({ 3, 24 }), 3.0, 1e-9);
    CHECK_NEAR(growthExponent({ 5, 5.2, 4.9, 5.1 }), std::log2(std::pow(5.1 / 5.0, 1.0 / 3)), 1e-9);
    CHECK_THROWS(growthExponent({ 4 }));
    CHECK_THROWS(growthExponent({ 0, 1 }));
}
TEST("naming the class") {
    CHECK_EQ(bigO(0.05), std::string("O(1)"));
    CHECK_EQ(bigO(-0.3), std::string("O(1)"));
    CHECK_EQ(bigO(1.1), std::string("O(n)"));
    CHECK_EQ(bigO(1.9), std::string("O(n^2)"));
    CHECK_EQ(bigO(3.2), std::string("O(n^3)"));
    CHECK_EQ(bigO(4.0), std::string("worse than O(n^3)"));
    CHECK_EQ(bigO(growthExponent({ 2.0, 8.1, 31.9, 128.4 })), std::string("O(n^2)"));
}

